static bool json_segment_set_size(json_object *jobj_segment, const uint64_t *size_bytes)
{
	json_object *jobj;

	if (!jobj_segment)
		return false;

	jobj = size_bytes ? crypt_jobj_new_uint64(*size_bytes) : json_object_new_string("dynamic");
	if (!jobj)
